arguments.command:
python3 - <<'EOF'
import json, urllib.request

def call(payload):
    req = urllib.request.Request(
        "https://slack.com/api/conversations.list",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"})
    return json.load(urllib.request.urlopen(req))

cursor = None
total = 0
matches = []
while True:
    p = {"token": "***", "types": "public_channel,private_channel", "limit": 1000}
    if cursor:
        p["cursor"] = cursor
    d = call(p)
    if not d.get("ok"):
        print("ERROR", d.get("error")); break
    for c in d.get("channels", []):
        total += 1
        if "incident" in c.get("name", "").lower():
            matches.append((c["id"], c["name"], c.get("is_archived"), c.get("topic", {}).get("text", "")))
    cursor = d.get("response_metadata", {}).get("next_cursor")
    if not cursor:
        break

print("total channels:", total)
for m in matches:
    print(m)
EOF

